SELECT count(*) AS recent_events
FROM "Events"
WHERE "Time" >= extract(epoch FROM now() - interval '24 hours') * 1000;

SELECT to_timestamp(max("Time") / 1000)                                    AS last_event_at,
       floor(extract(epoch FROM now() - to_timestamp(max("Time")/1000)) / 60)::int AS minutes_ago
FROM "Events";
